export function addROMPanel({getProject}){
 const anchor=document.getElementById('pico-session-status');if(!anchor)return;const chip=getProject().components.find(c=>c.type==='board')?.params.model,older=['pico','pico-h','pico-w','pico-wh'].includes(chip),section=document.createElement('section');section.innerHTML='<h3>Özgün ROM · salt okunur inceleme</h3><p>RP2040 B1 kodu gerçekten yürütülür; sıfırdan açılan ayrı bir oturumdur. Projenizin devresi ve flash belleği bu oturuma bağlı değildir. USB kapasite, INQUIRY ve sektör okuma desteklenir. Özgün ROM ile flash yazma, RP2350 ve CYW43 bu profilde desteklenmez.</p>'+(older?'<label>Yerel RP2040 B1 ROM .bin (16 KiB) <input data-rom-file type="file" accept=".bin"></label><label>Sektör (LBA) <input data-rom-lba type="number" min="0" max="65535" value="1"></label><button data-rom-command="msc-inquiry" disabled>ROM aygıt bilgisi</button> <button data-rom-command="msc-capacity" disabled>ROM disk kapasitesi</button> <button data-rom-command="msc-read" disabled>ROM sektörü oku</button>':'<p>Bu kart RP2350 kullanıyor. Güvenlik geçişleri tamamlanana kadar özgün ROM çalıştırma kapalıdır.</p>')+'<pre data-rom-state>ROM dosyası siteyle dağıtılmaz. Yalnız doğrulanan B1 görüntüsü kabul edilir.</pre>';anchor.after(section);if(!older)return;
 let worker=null,disposed=false;const state=section.querySelector('[data-rom-state]'),buttons=[...section.querySelectorAll('[data-rom-command]')];function busy(value){buttons.forEach(b=>b.disabled=value);}
 const cleanup=()=>{disposed=true;worker?.terminate();worker=null;};const observer=new MutationObserver(()=>{const dialog=section.closest('dialog');if(!section.isConnected||dialog&&!dialog.open){cleanup();observer.disconnect();}});observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});
 section.querySelector('[data-rom-file]').onchange=async e=>{const f=e.target.files[0];if(!f)return;const project=getProject();busy(true);try{if(f.size!==16384)throw Error('ROM dosyası tam 16384 bayt olmalı.');const rom=new Uint8Array(await f.arrayBuffer());if(disposed||getProject()!==project)return;worker?.terminate();worker=new Worker(new URL('./pico-rom-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data:d})=>{if(disposed)return;if(d.type==='rom-error'){state.textContent=d.message;busy(false);return;}const u=d.usb,t=u.msc;state.textContent=d.revision+' · özgün ROM kodu\nPC 0x'+d.pc.toString(16)+' · '+d.cycles+' çevrim\nUSB '+u.kind+' · '+(u.connected?'bağlı':'bekliyor')+(t?'\nSCSI '+t.status+' · '+t.bytes+' bayt\n'+t.hex:'');busy(false);};worker.onerror=err=>{state.textContent=err.message;busy(true);cleanup();};state.textContent='Özgün ROM açılıyor…';worker.postMessage({type:'load',chip,rom});}catch(err){state.textContent=err.message;busy(true);}e.target.value='';};
 buttons.forEach(button=>button.onclick=()=>{if(!worker)return;busy(true);state.textContent='ROM USB işlemi…';worker.postMessage({type:'command',action:button.dataset.romCommand,lba:Number(section.querySelector('[data-rom-lba]').value)});});
}
